selector_to_html = {"a[href=\"../autoapi/pyskyfire/ducts/orifice/OrificePlate.html#pyskyfire.ducts.orifice.OrificePlate.solve\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.orifice.OrificePlate.solve\">\n<span class=\"sig-name descname\"><span class=\"pre\">solve</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">inlet_state</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference internal\" href=\"../autoapi/pyskyfire/thermo/state/FluidState.html#pyskyfire.thermo.state.FluidState\" title=\"pyskyfire.thermo.state.FluidState\"><span class=\"pre\">FluidState</span></a></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">mass_flow</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">fluid</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">viscosity</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">|</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/constants.html#None\" title=\"(in Python v3.15)\"><span class=\"pre\">None</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><a class=\"reference internal\" href=\"../autoapi/pyskyfire/ducts/orifice/OrificePlateResult.html#pyskyfire.ducts.orifice.OrificePlateResult\" title=\"pyskyfire.ducts.orifice.OrificePlateResult\"><span class=\"pre\">OrificePlateResult</span></a></span></span></dt><dd><p>The tap-to-tap drop and permanent loss at <code class=\"docutils literal notranslate\"><span class=\"pre\">mass_flow</span></code>.</p></dd>", "a[href=\"../autoapi/pyskyfire/ducts/index.html#module-pyskyfire.ducts\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.ducts<a class=\"headerlink\" href=\"#module-pyskyfire.ducts\" title=\"Link to this heading\">\u00b6</a></h1><p>Duct hydraulics shared by cooling channels, piping and manifolds.</p><p>This subpackage contains shared path geometry, explicit pipe hydraulics,\nannular ducts, orifices and orifice plates, and volute and collector manifolds. It depends only on <a class=\"reference internal\" href=\"../autoapi/pyskyfire/common/index.html#module-pyskyfire.common\" title=\"pyskyfire.common\"><code class=\"xref py py-mod docutils literal notranslate\"><span class=\"pre\">pyskyfire.common</span></code></a> for\nplanar section primitives and friction correlations and <a class=\"reference internal\" href=\"../autoapi/pyskyfire/thermo/index.html#module-pyskyfire.thermo\" title=\"pyskyfire.thermo\"><code class=\"xref py py-mod docutils literal notranslate\"><span class=\"pre\">pyskyfire.thermo</span></code></a> for fluid state records,\nand it does not import from <a class=\"reference internal\" href=\"../autoapi/pyskyfire/regen/index.html#module-pyskyfire.regen\" title=\"pyskyfire.regen\"><code class=\"xref py py-mod docutils literal notranslate\"><span class=\"pre\">pyskyfire.regen</span></code></a> or <a class=\"reference internal\" href=\"../autoapi/pyskyfire/network/index.html#module-pyskyfire.network\" title=\"pyskyfire.network\"><code class=\"xref py py-mod docutils literal notranslate\"><span class=\"pre\">pyskyfire.network</span></code></a>,\nso cooling channels, turbopump hardware and engine-network adapters can all\ndepend on it without a cycle.</p>", "a[href=\"../autoapi/pyskyfire/ducts/orifice/OrificePlateResult.html#pyskyfire.ducts.orifice.OrificePlateResult.differential_pressure\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.orifice.OrificePlateResult.differential_pressure\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">property</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">differential_pressure</span></span><span class=\"property\"><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></dt><dd><p>Drop between the upstream and downstream taps [Pa].</p></dd>", "a[href=\"../autoapi/pyskyfire/ducts/orifice/Orifice.html#pyskyfire.ducts.orifice.Orifice\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.orifice.Orifice\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.orifice.</span></span><span class=\"sig-name descname\"><span class=\"pre\">Orifice</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">area</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">cd</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">hydraulic_diameter</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">length</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.0</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>A short restriction discharging into a large volume.</p><p class=\"rubric\">Notes</p><p>Use <a class=\"reference internal\" href=\"#pyskyfire.ducts.orifice.Orifice.circular\" title=\"pyskyfire.ducts.orifice.Orifice.circular\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">circular()</span></code></a>, <a class=\"reference internal\" href=\"#pyskyfire.ducts.orifice.Orifice.annular\" title=\"pyskyfire.ducts.orifice.Orifice.annular\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">annular()</span></code></a> or <a class=\"reference internal\" href=\"#pyskyfire.ducts.orifice.Orifice.slot\" title=\"pyskyfire.ducts.orifice.Orifice.slot\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">slot()</span></code></a> for those shapes.\nThe generic constructor takes any area, so an effective area quoted as\n<code class=\"docutils literal notranslate\"><span class=\"pre\">Cd\u00b7A</span></code> can be given as <code class=\"docutils literal notranslate\"><span class=\"pre\">Orifice(area=CdA,</span> <span class=\"pre\">cd=1.0)</span></code>.</p></dd>", "a[href=\"#pressure-drop-at-a-flow-or-flow-at-a-pressure-drop\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Pressure drop at a flow, or flow at a pressure drop<a class=\"headerlink\" href=\"#pressure-drop-at-a-flow-or-flow-at-a-pressure-drop\" title=\"Link to this heading\">\u00b6</a></h2><p>The flow expands isentropically from the inlet to the throat, so:</p>", "a[href=\"injectors.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Design and solve an injector<a class=\"headerlink\" href=\"#design-and-solve-an-injector\" title=\"Link to this heading\">\u00b6</a></h1><p>An injector in <code class=\"docutils literal notranslate\"><span class=\"pre\">pyskyfire.injector</span></code> is a list of element sets. Each set is one\nelement type repeated at face positions you supply. Holes are\n<code class=\"docutils literal notranslate\"><span class=\"pre\">ducts.Orifice</span></code> objects, so sizing, discharge coefficients, choking and\ncavitation work as in <a class=\"reference internal\" href=\"orifices.html\"><span class=\"doc\">Size and solve orifices</span></a>.</p><p>The injector frame is the scene frame: the face is the plane x = 0, the\nchamber lies towards +x, and a position <code class=\"docutils literal notranslate\"><span class=\"pre\">(r,</span> <span class=\"pre\">\u03b8)</span></code> on the face is\n<code class=\"docutils literal notranslate\"><span class=\"pre\">y</span> <span class=\"pre\">=</span> <span class=\"pre\">r</span> <span class=\"pre\">cos</span> <span class=\"pre\">\u03b8</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">z</span> <span class=\"pre\">=</span> <span class=\"pre\">r</span> <span class=\"pre\">sin</span> <span class=\"pre\">\u03b8</span></code>.</p>", "a[href=\"#in-an-engine-network\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">In an engine network<a class=\"headerlink\" href=\"#in-an-engine-network\" title=\"Link to this heading\">\u00b6</a></h2><p><code class=\"docutils literal notranslate\"><span class=\"pre\">OrificeBlock</span></code> replaces a fixed-ratio <code class=\"docutils literal notranslate\"><span class=\"pre\">SimpleDuctBlock</span></code> with the physical\nrestriction, such as a metering orifice in a film-cooling feed line:</p>", "a[href=\"#orifice-plates\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Orifice plates<a class=\"headerlink\" href=\"#orifice-plates\" title=\"Link to this heading\">\u00b6</a></h2><p>By default <code class=\"docutils literal notranslate\"><span class=\"pre\">cd</span></code> is the Reader-Harris/Gallagher correlation, which needs a\nviscosity. It is looked up from CoolProp, or passed as <code class=\"docutils literal notranslate\"><span class=\"pre\">viscosity=</span></code>\notherwise. Outside the geometry and Reynolds-number range of ISO 5167-2 the\ncorrelation is extrapolated, and <code class=\"docutils literal notranslate\"><span class=\"pre\">OrificeCorrelationWarning</span></code> says so.\nPass <code class=\"docutils literal notranslate\"><span class=\"pre\">cd=</span></code> to use a known value instead.</p><p>The plate uses ISO 5167\u2019s expansibility factor for gases rather than the\nisentropic nozzle expansion <code class=\"docutils literal notranslate\"><span class=\"pre\">Orifice</span></code> uses. A thin plate\u2019s jet keeps\ncontracting past the bore, and the two differ by about 1.6 % in the drop at a\n2.5 % tap drop in nitrogen.</p>", "a[href=\"../autoapi/pyskyfire/ducts/orifice/Orifice.html#pyskyfire.ducts.orifice.Orifice.circular\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.orifice.Orifice.circular\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">classmethod</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">circular</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">diameter</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">cd</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">length</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.0</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>A round hole of <code class=\"docutils literal notranslate\"><span class=\"pre\">diameter</span></code> [m].</p></dd>", "a[href=\"../autoapi/pyskyfire/ducts/orifice/OrificePlateResult.html#pyskyfire.ducts.orifice.OrificePlateResult\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.orifice.OrificePlateResult\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.orifice.</span></span><span class=\"sig-name descname\"><span class=\"pre\">OrificePlateResult</span></span></dt><dd><p>Bases: <code class=\"xref py py-obj docutils literal notranslate\"><span class=\"pre\">OrificeResult</span></code></p><p>An <code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">OrificeResult</span></code> with the plate\u2019s metering quantities.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">throat_state</span></code> is at the downstream tap, and\n<a class=\"reference internal\" href=\"#pyskyfire.ducts.orifice.OrificePlateResult.differential_pressure\" title=\"pyskyfire.ducts.orifice.OrificePlateResult.differential_pressure\"><code class=\"xref py py-attr docutils literal notranslate\"><span class=\"pre\">differential_pressure</span></code></a> is the tap-to-tap drop a flow meter reads.\n<code class=\"docutils literal notranslate\"><span class=\"pre\">outlet_state</span></code> is where the flow has recovered to the pipe bore, so\n<code class=\"xref py py-attr docutils literal notranslate\"><span class=\"pre\">pressure_loss</span></code> is the permanent loss, which is smaller.</p></dd>", "a[href=\"../autoapi/pyskyfire/network/blocks/OrificeBlock.html#pyskyfire.network.blocks.OrificeBlock\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.network.blocks.OrificeBlock\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.network.blocks.</span></span><span class=\"sig-name descname\"><span class=\"pre\">OrificeBlock</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">name</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/stdtypes.html#str\" title=\"(in Python v3.15)\"><span class=\"pre\">str</span></a></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">st_in</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/stdtypes.html#str\" title=\"(in Python v3.15)\"><span class=\"pre\">str</span></a></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">st_out</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/stdtypes.html#str\" title=\"(in Python v3.15)\"><span class=\"pre\">str</span></a></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">orifice</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">fluid</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">viscosity</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">|</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/constants.html#None\" title=\"(in Python v3.15)\"><span class=\"pre\">None</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Bases: <code class=\"xref py py-obj docutils literal notranslate\"><span class=\"pre\">FluidBlock</span></code></p><p>Engine-network adapter for one <code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">Orifice</span></code> or <code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">OrificePlate</span></code>.</p><p>The contained restriction remains independently usable through its own\n<code class=\"docutils literal notranslate\"><span class=\"pre\">solve</span></code>. This block only translates network stations into that public\nAPI and emits the outlet station and the <code class=\"docutils literal notranslate\"><span class=\"pre\">dp_&lt;name&gt;</span></code> loss signal. The\nsignal is the irreversible loss: the whole drop for an orifice, and the\npermanent loss after recovery for a plate.</p><p class=\"rubric\">Notes</p><p>The flow is adiabatic, so the outlet carries the inlet enthalpy.</p></dd>", "a[href=\"../autoapi/pyskyfire/thermo/index.html#module-pyskyfire.thermo\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.thermo<a class=\"headerlink\" href=\"#module-pyskyfire.thermo\" title=\"Link to this heading\">\u00b6</a></h1><p>Fluid properties, thermodynamic states and combustion-gas aerothermodynamics.</p><p>CEA-backed APIs are loaded on first access so fluid and nozzle-loss utilities\ncan be imported without loading CEA, including through the package root.</p>", "a[href=\"#size-a-hole-for-a-pressure-drop\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Size a hole for a pressure drop<a class=\"headerlink\" href=\"#size-a-hole-for-a-pressure-drop\" title=\"Link to this heading\">\u00b6</a></h2><p><code class=\"docutils literal notranslate\"><span class=\"pre\">required_area</span></code> returns the area alone, for other shapes. Both refuse a drop\nlarge enough to choke the flow, since such a hole would pass the flow at a\nsmaller drop.</p>", "a[href=\"#size-and-solve-orifices\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Size and solve orifices<a class=\"headerlink\" href=\"#size-and-solve-orifices\" title=\"Link to this heading\">\u00b6</a></h1><p><code class=\"docutils literal notranslate\"><span class=\"pre\">pyskyfire.ducts</span></code> has two restrictions described by a flow area and a\ndischarge coefficient:</p>", "a[href=\"../autoapi/pyskyfire/thermo/state/FluidState.html#pyskyfire.thermo.state.FluidState\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.state.FluidState\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.thermo.state.</span></span><span class=\"sig-name descname\"><span class=\"pre\">FluidState</span></span></dt><dd><p>Resolved bulk fluid state at one axial station.</p></dd>", "a[href=\"../autoapi/pyskyfire/ducts/orifice/Orifice.html#pyskyfire.ducts.orifice.Orifice.sized\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.orifice.Orifice.sized\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">classmethod</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">sized</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">mass_flow</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">inlet_state</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">dp</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">fluid</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">cd</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">length</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.0</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>The round hole that passes <code class=\"docutils literal notranslate\"><span class=\"pre\">mass_flow</span></code> with a pressure drop <code class=\"docutils literal notranslate\"><span class=\"pre\">dp</span></code>.</p><p>See <code class=\"xref py py-func docutils literal notranslate\"><span class=\"pre\">required_area()</span></code>.</p></dd>", "a[href=\"../autoapi/pyskyfire/ducts/orifice/Orifice.html#pyskyfire.ducts.orifice.Orifice.slot\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.orifice.Orifice.slot\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">classmethod</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">slot</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">width</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">height</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">cd</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">length</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.0</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>A rectangular slot of <code class=\"docutils literal notranslate\"><span class=\"pre\">width</span></code> by <code class=\"docutils literal notranslate\"><span class=\"pre\">height</span></code> [m].</p></dd>", "a[href=\"../autoapi/pyskyfire/index.html#module-pyskyfire\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire<a class=\"headerlink\" href=\"#module-pyskyfire\" title=\"Link to this heading\">\u00b6</a></h1><p>pyskyfire - A Python library for rocket engine simulation and design.</p>", "a[href=\"#define-an-orifice\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Define an orifice<a class=\"headerlink\" href=\"#define-an-orifice\" title=\"Link to this heading\">\u00b6</a></h2><p>The discharge coefficient is always supplied. Length is geometry only; it\ndoes not change <code class=\"docutils literal notranslate\"><span class=\"pre\">cd</span></code>.</p>", "a[href=\"../autoapi/pyskyfire/ducts/orifice/Orifice.html#pyskyfire.ducts.orifice.Orifice.annular\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.orifice.Orifice.annular\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">classmethod</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">annular</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">inner_diameter</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">outer_diameter</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">cd</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">length</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.0</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>The annulus between two concentric diameters [m], as around a coaxial post.</p></dd>", "a[href=\"../autoapi/pyskyfire/ducts/orifice/OrificeResult.html#pyskyfire.ducts.orifice.OrificeResult.pressure_loss\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.orifice.OrificeResult.pressure_loss\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">property</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">pressure_loss</span></span><span class=\"property\"><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></dt><dd><p>Irreversible pressure loss from inlet to outlet [Pa].</p></dd>", "a[href=\"../autoapi/pyskyfire/ducts/orifice/OrificePlate.html#pyskyfire.ducts.orifice.OrificePlate\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.orifice.OrificePlate\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.orifice.</span></span><span class=\"sig-name descname\"><span class=\"pre\">OrificePlate</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">pipe_diameter</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">orifice_diameter</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">cd</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">taps</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">'flange'</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">thickness</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.0</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>A thin round orifice plate in a straight pipe.</p><p class=\"rubric\">Notes</p><p>The flow follows ISO 5167,\n<span class=\"math notranslate nohighlight\">\\(\\dot m = C \\varepsilon A \\sqrt{2 \\rho_1 \\Delta p / (1 - \\beta^4)}\\)</span>,\nwith <a class=\"reference internal\" href=\"#pyskyfire.ducts.orifice.OrificePlate.expansibility\" title=\"pyskyfire.ducts.orifice.OrificePlate.expansibility\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">expansibility()</span></code></a> for \u03b5. That \u03b5 is fitted to thin plates, whose\njet keeps contracting past the bore, and it is not the isentropic nozzle\nexpansion <code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">Orifice</span></code> uses: for a gas at a 2.5 % tap drop the\nnozzle expansion would overstate the drop by about 1.6 %.</p><p>The permanent loss is ISO 5167-1\u2019s recovery relation,</p></dd>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
